        "titolo_orig": "Sparizioni forzate e il resto, Messico da cartellino rosso",
        "testo_it": "Amnesty International denuncia la piaga delle sparizioni forzate in Messico in concomitanza con l'inizio dei Mondiali.",
        "priorita": "Media",
        "id_gruppo": 3,
        "link": "https://ilmanifesto.it/sparizioni-forzate-e-il-resto-messico-da-cartellino-rosso",
        "orario": "00:07",
